# C2M2 scoring: a practice counts as performed if Fully (FI) or Largely (LI)
# Implemented; a MIL is earned only if every practice at that level AND all
# lower levels is performed (MILs are cumulative).
PERFORMED = {"FI", "LI"}

answers = {  # domain -> {MIL: [response per practice]}
    "ASSET":    {1: ["FI", "FI", "LI"], 2: ["LI", "PI", "FI"], 3: ["NI", "NI"]},
    "ACCESS":   {1: ["FI", "LI", "FI"], 2: ["FI", "FI", "LI"], 3: ["LI", "PI"]},
    "RESPONSE": {1: ["FI", "PI", "FI"], 2: ["FI", "FI", "FI"], 3: ["FI", "FI"]},
}
target = {"ASSET": 2, "ACCESS": 2, "RESPONSE": 3}

def mil(levels):
    earned = 0
    for level in (1, 2, 3):
        if all(r in PERFORMED for r in levels[level]):
            earned = level
        else:
            break          # cumulative: a gap stops the climb
    return earned

for d, levels in answers.items():
    m = mil(levels)
    gap = "meets target" if m >= target[d] else f"gap of {target[d] - m}"
    print(f"{d:<9} MIL{m}  target MIL{target[d]}  {gap}")
